// Test file: src/app/routes/article/article.model.spec.ts

import { Article } from './article.model';

describe('Article Model', () => {
  describe('Article interface/type validation', () => {
    it('should create a valid article object with all required fields', () => {
      const article: Article = {
        id: 1,
        slug: 'test-article',
        title: 'Test Article',
        description: 'Test description',
        body: 'Test body content',
        tagList: ['test', 'article'],
        createdAt: new Date(),
        updatedAt: new Date(),
        favorited: false,
        favoritesCount: 0,
        author: {
          username: 'testuser',
          bio: 'Test bio',
          image: 'https://example.com/image.jpg',
          following: false
        }
      };

      expect(article).toBeDefined();
      expect(article.slug).toBe('test-article');
      expect(article.title).toBe('Test Article');
    });

    it('should handle optional fields correctly', () => {
      const minimalArticle: Partial<Article> = {
        slug: 'minimal-article',
        title: 'Minimal Article'
      };

      expect(minimalArticle.slug).toBe('minimal-article');
      expect(minimalArticle.body).toBeUndefined();
    });

    it('should validate article with empty tag list', () => {
      const article: Partial<Article> = {
        slug: 'no-tags',
        title: 'Article without tags',
        tagList: []
      };

      expect(article.tagList).toEqual([]);
      expect(article.tagList?.length).toBe(0);
    });

    it('should handle favorited state correctly', () => {
      const favoritedArticle: Partial<Article> = {
        slug: 'favorited',
        favorited: true,
        favoritesCount: 5
      };

      expect(favoritedArticle.favorited).toBe(true);
      expect(favoritedArticle.favoritesCount).toBe(5);
    });
  });

  describe('Article data transformations', () => {
    it('should handle date serialization correctly', () => {
      const now = new Date();
      const article: Partial<Article> = {
        createdAt: now,
        updatedAt: now
      };

      expect(article.createdAt).toBeInstanceOf(Date);
      expect(article.updatedAt).toBeInstanceOf(Date);
    });

    it('should validate author nested object structure', () => {
      const article: Partial<Article> = {
        author: {
          username: 'john_doe',
          bio: 'Software developer',
          image: 'https://example.com/avatar.jpg',
          following: true
        }
      };

      expect(article.author?.username).toBe('john_doe');
      expect(article.author?.following).toBe(true);
    });
  });
});

